<template><main class="gateway-admin"><header><div><p class="eyebrow">TrastPay</p><h1>CleanPay / Promerica</h1><p>Configure the API and 3DS without exposing the token.</p></div><button class="primary" :disabled="saving" @click="save">{{saving?'Saving…':'Save'}}</button></header><section class="panel"><div class="grid"><label><span>Enabled</span><input v-model="form.enabled" type="checkbox"></label><label><span>3DS enabled</span><input v-model="form.threeDsEnabled" type="checkbox"></label><label class="wide"><span>API URL</span><input v-model="form.apiUrl" required></label><label><span>Merchant ID</span><input v-model="form.merchantId"></label><label><span>Terminal ID</span><input v-model="form.terminalId"></label><label><span>Authorization header</span><input v-model="form.authHeader"></label><label><span>Authorization scheme</span><input v-model="form.authScheme" placeholder="Bearer"></label><label class="wide"><span>Token {{form.tokenConfigured?'(configured)':''}}</span><input v-model="form.token" type="password" autocomplete="new-password" placeholder="Leave blank to keep the current token"></label><label class="wide"><span>3DS return URL</span><input v-model="form.returnUrl"></label><label class="wide"><span>3DS cancel URL</span><input v-model="form.cancelUrl"></label><label><span>Timeout (seconds)</span><input v-model.number="form.timeoutSeconds" type="number" min="5" max="120"></label><label class="wide"><span>Additional request JSON</span><textarea v-model="form.additionalJson" rows="6"></textarea></label></div></section><p v-if="message" class="message">{{message}}</p></main></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';const form=reactive<any>({enabled:false,threeDsEnabled:true,authHeader:'Authorization',authScheme:'Bearer',timeoutSeconds:30,token:''}),saving=ref(false),message=ref('');async function request(init?:RequestInit){const r=await fetch('/api/admin/commerce/gateways/cleanpay',{credentials:'include',headers:{'Content-Type':'application/json'},...init});if(!r.ok)throw new Error(await r.text());return r.json()}onMounted(async()=>Object.assign(form,await request()));async function save(){saving.value=true;try{Object.assign(form,await request({method:'PUT',body:JSON.stringify(form)}));form.token='';message.value='CleanPay configuration saved.'}catch(e:any){message.value=e.message}finally{saving.value=false}}</script><style scoped>.gateway-admin{display:grid;gap:1.25rem;padding:1.25rem;max-width:980px;margin:auto}.gateway-admin header{display:flex;justify-content:space-between;gap:1rem}.panel{background:var(--panel-bg,#fff);border:1px solid var(--border-color,#e4e7ec);border-radius:.75rem;padding:1.25rem}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.wide{grid-column:1/-1}label{display:grid;gap:.35rem}input,textarea{padding:.65rem;border:1px solid var(--border-color,#d0d5dd);border-radius:.5rem;background:inherit;color:inherit}.primary{background:var(--primary,#4f46e5);color:#fff;border:0;border-radius:.5rem;padding:.7rem 1rem}@media(max-width:720px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}.gateway-admin header{flex-direction:column}}</style>